-- 阅读端测试数据：100 本热门小说，每本 3 章。
-- 本文件使用独立 ID 区间 1001-1100、章节 10001-10300，不删除现有数据。
USE `novel`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;
START TRANSACTION;

ON DUPLICATE KEY UPDATE book_name = VALUES(book_name), author_name = VALUES(author_name), category_id = VALUES(category_id), pic_url = VALUES(pic_url), book_desc = VALUES(book_desc), book_status = VALUES(book_status), word_count = VALUES(word_count), visit_count = VALUES(visit_count), chapter_count = VALUES(chapter_count), first_chapter_id = VALUES(first_chapter_id), last_chapter_id = VALUES(last_chapter_id), last_chapter_name = VALUES(last_chapter_name), last_chapter_update_time = VALUES(last_chapter_update_time), status = VALUES(status), create_time = VALUES(create_time), update_time = VALUES(update_time);

ON DUPLICATE KEY UPDATE book_id = VALUES(book_id), chapter_num = VALUES(chapter_num), chapter_name = VALUES(chapter_name), word_count = VALUES(word_count), update_time = VALUES(update_time), create_time = VALUES(create_time);

ON DUPLICATE KEY UPDATE chapter_id = VALUES(chapter_id), content = VALUES(content), create_time = VALUES(create_time), update_time = VALUES(update_time);

COMMIT;
SELECT COUNT(*) AS test_book_count FROM `book_info` WHERE `id` BETWEEN 1001 AND 1100;
SELECT COUNT(*) AS test_chapter_count FROM `book_chapter` WHERE `id` BETWEEN 10001 AND 10300;
SELECT COUNT(*) AS test_content_count FROM `book_content` WHERE `chapter_id` BETWEEN 10001 AND 10300;